var builder=WebApplication.CreateBuilder(args); builder.Services.AddControllersWithViews(); builder.Services.AddHttpClient("LibraryApi",c=>c.BaseAddress=new Uri(builder.Configuration["LibraryApi:BaseUrl"]!)); var app=builder.Build(); if(!app.Environment.IsDevelopment()){app.UseExceptionHandler("/Home/Error");app.UseHsts();} if(!app.Environment.IsDevelopment()) app.UseHttpsRedirection();app.UseStaticFiles();app.UseRouting();app.MapControllerRoute(name:"default",pattern:"{controller=Home}/{action=Index}/{id?}");app.Run();